<?php require_once __DIR__.'/mahasiswa_helper.php'; wajib_role(['ADMIN','OPERATOR_PRODI','DEKANAT','REKTORAT']);$r=mahasiswa_soa('list',['cari'=>$_GET['cari']??'','status'=>$_GET['status']??'']);$rows=mahasiswa_data($r,'mahasiswa');include __DIR__.'/topbar.php';include __DIR__.'/sideleftbar.php'; ?>
<main class="main-content"><h1>Data Mahasiswa</h1><form method="get"><input name="cari" placeholder="Cari NPM/nama" value="<?=mahasiswa_h($_GET['cari']??'')?>"><select name="status"><option value="">Semua status</option><?php foreach(['Aktif','Cuti','Lulus','Mengundurkan Diri','Drop Out','Tidak Aktif'] as $s):?><option <?=($_GET['status']??'')===$s?'selected':''?>><?=mahasiswa_h($s)?></option><?php endforeach;?></select><button class="btn btn-primary">Cari</button></form><div class="dashboard-panel"><table class="table"><thead><tr><th>NPM</th><th>Nama</th><th>Program Studi</th><th>Fakultas</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $m):?><tr><td><?=mahasiswa_h($m['npm'])?></td><td><?=mahasiswa_h($m['nama_mahasiswa'])?></td><td><?=mahasiswa_h($m['nama_program_studi'])?></td><td><?=mahasiswa_h($m['nama_fakultas'])?></td><td><?=mahasiswa_h($m['status_mahasiswa'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows)echo '<p>Data tidak tersedia.</p>';?></div></main>
